// Synthetic diagram snapshots for the explainer property tests: nodes, owned
// labels, scaffolding and links (parallel and self links included), shaped
// like the snapshots Agentic Mermaid's importer writes, generated by
// fast-check so failures shrink to the smallest diagram that shows them.
import { fc } from './pbt.ts';
import { Rectangle } from '../../src/index.ts';
import type { DiagramSnapshot, SnapshotPart, SnapshotShape } from '../../integrations/agentic-mermaid/snapshot.ts';
import type { Style } from '../../src/index.ts';

const HEX = fc
  .tuple(fc.integer({ min: 0, max: 255 }), fc.integer({ min: 0, max: 255 }), fc.integer({ min: 0, max: 255 }))
  .map(([r, g, b]) => '#' + [r, g, b].map((n) => n.toString(16).padStart(2, '0')).join(''));
export const hexColor = HEX;

const unit = fc.double({ min: 0, max: 1, noNaN: true });
const style = (fill: fc.Arbitrary<string>, stroke: fc.Arbitrary<string>): fc.Arbitrary<Style> =>
  fc.record({
    fill,
    stroke,
    strokeWidth: fc.double({ min: 0, max: 0.2, noNaN: true }),
    fillOpacity: unit,
    strokeOpacity: unit,
    opacity: unit,
  });

function rect(x: number, y: number, w: number, h: number, s: Style): SnapshotShape {
  const m = new Rectangle({ width: w, height: h }).moveTo([x, y]);
  return { subpaths: m.subpaths.map((a) => Array.from(a)), closed: [...m.closed], style: s };
}

export interface SnapshotPlan {
  family: string;
  width: number;
  height: number;
  nodes: { id: string; x: number; y: number; w: number; h: number; style: Style; label: Style | null }[];
  links: { from: number; to: number; role: 'edge' | 'message'; line: Style; head: Style | null }[];
  frame: Style | null;
  lifeline: Style | null;
  palette: { paper: string; ink: string; accent: string; muted: string };
}

/** Node ids: short names, including ones that look like the prefixes `get` resolves. */
const nodeId = fc.oneof(
  fc.stringMatching(/^[A-Za-z][A-Za-z0-9_]{0,4}$/),
  fc.string({ unit: 'grapheme', minLength: 1, maxLength: 4 }),
  fc.constantFrom('node', 'class', 'state', 'x y', '->', '#0'),
);

export const snapshotPlan: fc.Arbitrary<SnapshotPlan> = fc
  .record({
    family: fc.constantFrom('flowchart', 'state', 'class', 'mindmap', 'sequence', 'gitgraph', 'xychart', 'er'),
    width: fc.integer({ min: 50, max: 2000 }),
    height: fc.integer({ min: 50, max: 1200 }),
    ids: fc.uniqueArray(nodeId, { minLength: 0, maxLength: 6 }),
    geometry: fc.array(
      fc.record({
        x: fc.double({ min: -2, max: 20, noNaN: true }),
        y: fc.double({ min: -12, max: 2, noNaN: true }),
        w: fc.double({ min: 0.05, max: 3, noNaN: true }),
        h: fc.double({ min: 0.05, max: 2, noNaN: true }),
        style: style(HEX, HEX),
        label: fc.option(style(HEX, fc.constant('none'))),
      }),
      { minLength: 6, maxLength: 6 },
    ),
    links: fc.array(
      fc.record({
        from: fc.nat(),
        to: fc.nat(),
        role: fc.constantFrom('edge' as const, 'message' as const),
        line: style(fc.constant('none'), HEX),
        head: fc.option(style(HEX, fc.constant('none'))),
      }),
      { maxLength: 8 },
    ),
    frame: fc.option(style(HEX, HEX)),
    lifeline: fc.option(style(fc.constant('none'), HEX)),
    palette: fc.record({ paper: HEX, ink: HEX, accent: HEX, muted: HEX }),
  })
  .map(({ ids, geometry, links, ...rest }) => ({
    ...rest,
    nodes: ids.map((id, i) => ({ id, ...geometry[i]! })),
    links: ids.length ? links.map((l) => ({ ...l, from: l.from % ids.length, to: l.to % ids.length })) : [],
  }));

/** The snapshot a plan describes; part ids are unique (plans whose node ids collide with link ids are dropped). */
export function buildSnapshot(plan: SnapshotPlan, source = 'graph'): DiagramSnapshot {
  const parts: SnapshotPart[] = [];
  if (plan.frame)
    parts.push({ id: '__frame', role: 'frame', kind: 'shape', svg: '', shapes: [rect(plan.width / 200, -plan.height / 200, plan.width / 100, plan.height / 100, plan.frame)] });
  if (plan.lifeline)
    parts.push({ id: 'lifeline:0', role: 'lifeline', kind: 'shape', svg: '', shapes: [rect(0.5, -plan.height / 200, 0.02, plan.height / 100, plan.lifeline)] });
  for (const n of plan.nodes) {
    parts.push({ id: n.id, role: 'node', kind: 'shape', svg: '', shapes: [rect(n.x, n.y, n.w, n.h, n.style)] });
    if (n.label)
      parts.push({
        id: 'label:' + n.id,
        owner: n.id,
        role: 'node-label',
        kind: 'text',
        svg: '',
        shapes: [{ ...rect(n.x, n.y, n.w / 2, n.h / 3, n.label), text: n.id, fontSize: n.h / 3 }],
      });
  }
  const perPair = new Map<string, number>();
  for (const l of plan.links) {
    const a = plan.nodes[l.from]!,
      b = plan.nodes[l.to]!;
    const pair = `${a.id}->${b.id}`;
    const k = perPair.get(pair) ?? 0;
    perPair.set(pair, k + 1);
    const route: [number, number][] =
      l.from === l.to
        ? [[a.x, a.y], [a.x + 1, a.y + 1], [a.x, a.y + 0.5]]
        : [[a.x, a.y], [b.x, b.y]];
    const [x0, y0] = route[0]!,
      [x1, y1] = route.at(-1)!;
    const shapes = [rect((x0 + x1) / 2, (y0 + y1) / 2, Math.max(0.02, Math.abs(x1 - x0)), 0.02, l.line)];
    if (l.head) shapes.push(rect(x1, y1, 0.1, 0.1, l.head));
    parts.push({ id: `edge:${pair}#${k}`, role: l.role, kind: 'connector', svg: '', shapes, from: a.id, to: b.id, route });
  }
  return {
    version: 1,
    renderer: 'agentic-mermaid@0.4.1',
    spec: { source, style: 'nord' },
    family: plan.family,
    width: plan.width,
    height: plan.height,
    palette: plan.palette,
    svg: '',
    findings: { ok: true, warnings: [] },
    parts,
  };
}

export const uniqueIds = (s: DiagramSnapshot) => new Set(s.parts.map((p) => p.id)).size === s.parts.length;

/** Snapshots with unique part ids, ready for a Diagram. */
export const snapshot = (source = 'graph') => snapshotPlan.map((p) => buildSnapshot(p, source)).filter(uniqueIds);
